const payload = $input.item.json || {};
const msg = payload.message || payload.body?.message || payload.payload?.message || {};

const rawText = String(
  payload.rawText ||
  payload.text ||
  msg.text ||
  msg.caption ||
  payload.payload?.text ||
  payload.payload?.rawText ||
  ''
).trim();

const chatId =
  payload.chatId ||
  msg.chat?.id ||
  payload.payload?.chatId ||
  payload.payload?.message?.chat?.id ||
  '';

const document = payload.document || msg.document || payload.payload?.document || payload.payload?.message?.document || null;
const photo = payload.photo || msg.photo || payload.payload?.photo || payload.payload?.message?.photo || null;
const video = payload.video || msg.video || payload.payload?.video || payload.payload?.message?.video || null;
const audio = payload.audio || msg.audio || msg.voice || payload.payload?.audio || payload.payload?.message?.audio || payload.payload?.message?.voice || null;

const hasDocument = Boolean(document);
const hasPhoto = Boolean(photo);
const hasVideo = Boolean(video);
const hasAudio = Boolean(audio);
const hasAttachment = Boolean(payload.hasAttachment || hasDocument || hasPhoto || hasVideo || hasAudio);

const fileId = payload.fileId || document?.file_id || video?.file_id || audio?.file_id || '';
const fileName = payload.fileName || document?.file_name || video?.file_name || audio?.file_name || '';
const mimeType = payload.mimeType || document?.mime_type || video?.mime_type || audio?.mime_type || '';

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

const text = normalize(rawText);
function hasAny(keywords) { return keywords.some((k) => text.includes(k)); }

let action = 'help';

if (hasAny(['drive help','huong dan drive','dung drive nhu the nao','google drive help'])) action = 'help';
else if (hasAny(['xem drive','xem file drive','file gan day','liet ke file','danh sach file','list drive files','recent files'])) action = 'list_files';
else if (hasAny(['tim file','search file','kiem file','tim trong drive','find file'])) action = 'search_file';
else if (hasAny(['thong tin file','chi tiet file','file info','metadata file','noi dung file','doc file','read file'])) action = 'get_file_info';
else if (hasAny(['tao folder','tao thu muc','create folder'])) action = 'create_folder';
else if (hasAny(['tao file','tao tep','create file'])) action = 'create_file';
else if (hasAny(['upload file','upload tep','luu file nay vao drive','luu tep nay vao drive','tai file nay len drive','tai tep nay len drive','tai len drive','luu vao drive','up file'])) action = 'upload_file';
else if (hasAttachment && hasAny(['upload','luu','tai len'])) action = 'upload_file';
else if (hasAny(['download file','tai file','tai tep','gui toi file','lay file','tai xuong file','send me file'])) action = 'download_file';
else if (hasAny(['copy file','nhan ban file','tao ban sao file','duplicate file','copy template'])) action = 'copy_file';
else if (hasAny(['doi ten file','rename file','doi ten thu muc']) || /doi ten .+ thanh .+/.test(text)) action = 'rename_file';
else if (hasAny(['di chuyen file','move file','chuyen file','dua file'])) action = 'move_file';
else if (hasAny(['xoa folder','xoa thu muc','delete folder','delete directory'])) action = 'delete_folder';
else if (hasAny(['xoa file','delete file','bo file vao thung rac','move file to trash'])) action = 'delete_file';
else if (hasAny(['share file','chia se file','cap quyen file','give access','share folder','chia se folder','cap quyen folder'])) action = 'share_file';
else if (hasAny(['xuat file','export file','chuyen file sang','export sheet'])) action = 'export_file';
else if (hasAny(['drive','google drive'])) action = 'list_files';

return [{
  json: {
    ...payload,
    payload,
    message: msg,
    chatId,
    rawText,
    text,
    action,
    hasAttachment,
    hasDocument,
    hasPhoto,
    hasVideo,
    hasAudio,
    document,
    photo,
    video,
    audio,
    fileId,
    fileName,
    mimeType
  }
}];

const workflows = $input.item.json.data || [];
const source = $('Chon Workflow Drive').item.json;
const found = workflows.find((workflow) => workflow.name === source.workflowName);
if (!found) return [{ json: { ...source, hasWorkflow: false, response: 'Khong tim thay workflow con: ' + source.workflowName } }];
return [{ json: { ...source, hasWorkflow: true, workflowId: found.id } }];

const source = $json || {};
const fallback = source.response || '⚠️ Mia chưa xử lý được yêu cầu này lúc này.';
return [{ json: { chatId: source.chatId || '', text: fallback } }];
